package org.circus.core;
import java.io.*;
import java.util.*;

/** Explicit self-authored PE32 fixtures, not a bundled original executable.
 * Actual CHS byte/getter references are exercised by the separate readonly audit. */
public final class Pc1StaticImageTests {
 private static int checks;
 private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private interface Work{void run()throws IOException;}
 private static void reject(Work work,String text)throws IOException{boolean failed=false;try{work.run();}catch(IOException expected){failed=expected.getMessage().contains(text);}check(failed,"precise "+text);}
 private static void u16(byte[] raw,int at,int value){raw[at]=(byte)value;raw[at+1]=(byte)(value>>>8);}
 private static void u32(byte[] raw,int at,int value){for(int n=0;n<4;n++)raw[at+n]=(byte)(value>>>(n*8));}
 private static byte[] pe(int base){byte[] raw=new byte[0xa00];u16(raw,0,0x5a4d);u32(raw,0x3c,0x80);u32(raw,0x80,0x4550);u16(raw,0x84,0x14c);u16(raw,0x86,3);u16(raw,0x94,224);int o=0x98;u16(raw,o,0x10b);u32(raw,o+28,base);u32(raw,o+32,0x1000);u32(raw,o+36,0x200);u32(raw,o+56,0x10000);u32(raw,o+60,0x400);u32(raw,o+92,16);u32(raw,o+96+12*8,0x2020);u32(raw,o+100+12*8,8);String[] names={".text",".rdata",".data"};for(int n=0;n<3;n++){int h=o+224+n*40;for(int b=0;b<names[n].length();b++)raw[h+b]=(byte)names[n].charAt(b);u32(raw,h+8,n==2?0x3000:0x200);u32(raw,h+12,(n+1)*0x1000);u32(raw,h+16,0x200);u32(raw,h+20,0x400+n*0x200);u32(raw,h+36,n==0?0x60000020:n==1?0x40000040:0xc0000040);for(int b=0;b<0x200;b++)raw[0x400+n*0x200+b]=(byte)(n*31+b*37+19);}return raw;}
 private static Pc1StaticImage.Seed seed(byte[] raw)throws IOException{return Pc1StaticImage.Seed.fixture(raw,Binary.sha256(raw),"self-authored PE preferred-address reference V1");}
 private static Pc1NativeMemory bus(){return new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){final byte[] bytes=new byte[Pc1NativeSettings.SIZE];public int read(int at){return bytes[at]&255;}public void write(int at,int value){bytes[at]=(byte)value;}});}
 private static Pc1NativeMemory.Region borrowed(final byte[] raw){return new Pc1NativeMemory.Region(){public int read(int n){return raw[n]&255;}public void write(int n,int value){raw[n]=(byte)value;}};}
 private static byte[] save(Pc1StaticImage image)throws IOException{ByteArrayOutputStream raw=new ByteArrayOutputStream();image.save(new DataOutputStream(raw));return raw.toByteArray();}
 private static Pc1StaticImage.Image load(byte[] raw,Pc1StaticImage.Seed seed)throws IOException{return Pc1StaticImage.loadImage(new DataInputStream(new ByteArrayInputStream(raw)),seed);}
 private static int changes(byte[] raw)throws IOException{ByteArrayInputStream bytes=new ByteArrayInputStream(raw);DataInputStream in=new DataInputStream(bytes);in.readInt();in.readInt();in.readUTF();in.readUTF();in.readUTF();in.readInt();in.readInt();in.readInt();return raw.length-bytes.available();}
 private static int readI32(Pc1NativeMemory memory,int address)throws IOException{int value=0;for(int n=0;n<4;n++)value|=memory.readAddress(address+n)<<(n*8);return value;}
 private static void admission()throws IOException{
  byte[] raw=pe(0x400000);String sha=Binary.sha256(raw);Pc1StaticImage.Seed seed=seed(raw);raw[0x400]=99;Pc1NativeMemory memory=bus();Pc1StaticImage image=new Pc1StaticImage(seed);reject(()->save(image),"must be finalized");memory.finalizeStaticImage(image);check(memory.readAddress(0x401000)==19,"immutable seed clone, not caller's changed PE bytes");reject(()->Pc1StaticImage.Seed.fixture(raw,sha,"changed"),"SHA256 mismatch");reject(()->Pc1StaticImage.Seed.readPreferredPc1Chs(pe(0x400000)),"SHA256 mismatch");byte[] broken=pe(0x400000);broken[0]=0;reject(()->seed(broken),"DOS/PE32");byte[] tls=pe(0x400000);u32(tls,0x98+96+9*8,0x3020);u32(tls,0x98+100+9*8,24);reject(()->seed(tls),"unsupported relocation/TLS");byte[] truncated=Arrays.copyOf(pe(0x400000),0x900);reject(()->seed(truncated),"truncated PE source");
  check(memory.readAddress(0x403000)==81&&memory.readAddress(0x403200)==0&&memory.readAddress(0x405fff)==0,"actual raw prefix plus known zero-filled virtual suffix, not blanket process zero");reject(()->memory.readAddress(0x400001),"unowned neighboring");reject(()->memory.readAddress(0x401200),"unowned neighboring");reject(()->memory.readAddress(0x406000),"unowned neighboring");reject(()->memory.readAddress(0x402020),"loader IAT");reject(()->memory.writeAddress(0x402020,0),"loader IAT");check(image.changedPageCount()==0,"IAT raw hint is never exposed as a real pointer or overwritten");reject(()->memory.writeAddress(0x401000,0),"readonly section");reject(()->memory.writeAddress(0x402008,0),"readonly section");check(memory.readAddress(0x401000)==19&&image.changedPageCount()==0,"RO failures preserve source and create no RW pages");
  memory.finalizeStaticImage(image);check(memory.staticImage()==image,"same final owner attach idempotent");reject(()->memory.finalizeStaticImage(new Pc1StaticImage(seed)),"another static image");reject(()->memory.bind(0x403100,4,borrowed(new byte[4])),"fixed-owner layout is finalized");Pc1NativeMemory other=bus();reject(()->other.finalizeStaticImage(image),"another native bus");check(other.staticImage()==null,"failed owner reuse leaves second bus unfinalized");
 }
 private static void borrowedAndSparse()throws IOException{
  Pc1StaticImage.Seed seed=seed(pe(0x400000));Pc1NativeMemory memory=bus();byte[] fixed={0x11,0x22,0x33,0x44};memory.bind(0x4031fe,4,borrowed(fixed));byte[] typedImport={5,7,11,13};memory.bind(0x402020,4,borrowed(typedImport));Pc1StaticImage image=new Pc1StaticImage(seed);memory.finalizeStaticImage(image);check(memory.readAddress(0x402020)==5,"explicit native typed import owner overrides exclusion without exposing raw hint");reject(()->memory.readAddress(0x402024),"loader IAT");check(!image.owns(0x4031fe)&&image.owns(0x4031fd)&&image.owns(0x403202),"static owner subtracts precise fixed spans across raw/BSS boundary");reject(()->image.read(0x4031fe),"another owner");fixed[1]=0x66;check(memory.readAddress(0x4031ff)==0x66,"borrowed fixed bytes remain the original canonical owner");int before=memory.readAddress(0x4031fd);check(readI32(memory,0x4031fd)==(before|0x11<<8|0x66<<16|0x33<<24),"DWORD reads cross static gap and fixed owner in original address order");memory.writeAddress(0x4031fd,77);memory.writeAddress(0x4031ff,29);memory.writeAddress(0x403202,99);check(fixed[1]==29&&image.changedByteCount()==2&&image.changedPageCount()==1,"same-page writes store only static bytes, never duplicate borrowed state");memory.writeAddress(0x404001,251);memory.writeAddress(0x405fff,37);check(image.changedPageCount()==3&&image.changedByteCount()==4,"RW pages allocate only on an actual nonseed change");memory.writeAddress(0x404001,0);check(image.changedPageCount()==2&&image.changedByteCount()==3,"return to seed removes empty COW page");byte[] saved=save(image);check(saved.length<600,"sparse codec stores only changed bytes instead of three full pages or borrowed values");Pc1NativeMemory restoredBus=bus();byte[] newFixed={1,2,3,4};restoredBus.bind(0x4031fe,4,borrowed(newFixed));restoredBus.bind(0x402020,4,borrowed(new byte[]{8,9,10,11}));Pc1StaticImage restored=new Pc1StaticImage(seed);restoredBus.finalizeStaticImage(restored);restored.restore(load(saved,seed));check(restoredBus.readAddress(0x4031fd)==77&&restoredBus.readAddress(0x403202)==99&&restoredBus.readAddress(0x405fff)==37,"sparse restore carries native gap values");check(Arrays.equals(newFixed,new byte[]{1,2,3,4})&&restoredBus.readAddress(0x402020)==8,"restoring image never restores independent fixed/typed import owner");restoredBus.writeAddress(0x403202,21);check(memory.readAddress(0x403202)==99,"restored pages detached from the source world's COW state");
  Pc1NativeMemory differentBus=bus();differentBus.bind(0x4031ff,4,borrowed(new byte[4]));Pc1StaticImage different=new Pc1StaticImage(seed);differentBus.finalizeStaticImage(different);reject(()->different.restore(load(saved,seed)),"fixed-layout/exclusion fingerprint");check(different.changedByteCount()==0,"layout mismatch does not partially publish any page");Pc1NativeMemory extraBus=bus();extraBus.bind(0x4031fe,4,borrowed(new byte[4]));extraBus.bind(0x402020,4,borrowed(new byte[4]));Pc1StaticImage extra=new Pc1StaticImage(seed,Arrays.asList(new Pc1StaticImage.Exclusion(0x404000,4,"explicit other startup mutation")));extraBus.finalizeStaticImage(extra);reject(()->extra.restore(load(saved,seed)),"fixed-layout/exclusion fingerprint");reject(()->load(saved,Pc1StaticImage.Seed.fixture(pe(0x400000),Binary.sha256(pe(0x400000)),"different target authority")),"seed/phase identity");
  memory.writeAddress(0x4031fd,before);memory.writeAddress(0x403202,0);memory.writeAddress(0x405fff,0);check(image.changedPageCount()==0&&image.changedByteCount()==0&&fixed[1]==29,"discarding static diffs leaves unrelated modified fixed state intact");
 }
 private static void damagedAndGuest()throws IOException{
  Pc1StaticImage.Seed seed=seed(pe(0x400000));Pc1NativeMemory memory=bus();memory.bind(0x4031fe,4,borrowed(new byte[4]));Pc1StaticImage image=new Pc1StaticImage(seed);memory.finalizeStaticImage(image);memory.writeAddress(0x403500,17);byte[] raw=save(image);int first=changes(raw);byte[] same=raw.clone();same[first+2]=0;reject(()->load(same,seed),"sparse byte descriptor");byte[] claimed=raw.clone();claimed[first]=1;claimed[first+1]=(byte)0xfe;Pc1StaticImage.Image damaged=load(claimed,seed);reject(()->image.restore(damaged),"cannot overwrite borrowed");check(memory.readAddress(0x403500)==17&&image.changedByteCount()==1,"damaged snapshot cannot erase prior native COW state");
  Pc1GuestAddressSpace guest=new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());Pc1NativeMemory shared=bus();guest.bindTo(shared);Pc1StaticImage safe=new Pc1StaticImage(seed);shared.finalizeStaticImage(safe);Pc1HeapLease dynamic=Pc1HeapLease.fixture32(0xe00000,new byte[]{41,43,47,53},"explicit physical private reference");int pointer=guest.mapBorrowed(dynamic);check(shared.readAddress(pointer)==41&&guest.read(0x403200)==0&&guest.read(0x401000)==19,"one bus reaches static holes and guest heap through the same source order");guest.write(0x403200,93);check(shared.readAddress(0x403200)==93&&safe.changedByteCount()==1,"Guest static fallback aliases same COW storage");
  Pc1StaticImage.Seed high=seed(pe(0x10000000));Pc1GuestAddressSpace highArena=new Pc1GuestAddressSpace(new Pc1GuestAddressSpace.Layout(0x10000000,0x10010000L,8));Pc1NativeMemory conflict=bus();highArena.bindTo(conflict);Pc1StaticImage bad=new Pc1StaticImage(high);reject(()->conflict.finalizeStaticImage(bad),"overlaps Guest32 arena");check(conflict.staticImage()==null&&!bad.finalized(),"collision fails before publishing static image");Pc1NativeMemory reverse=bus();reverse.finalizeStaticImage(new Pc1StaticImage(high));Pc1GuestAddressSpace arenaAfter=new Pc1GuestAddressSpace(new Pc1GuestAddressSpace.Layout(0x10000000,0x10010000L,8));reject(()->arenaAfter.bindTo(reverse),"overlaps Guest32 arena");check(reverse.guestAddressSpace()==null,"late Guest collision cannot conceal prior static bytes");
 }
 public static int run()throws Exception{checks=0;admission();borrowedAndSparse();damagedAndGuest();return checks;}
 public static void main(String[] args)throws Exception{System.out.println("PASS Pc1StaticImageTests "+run());}
}
